package com.htttdn.crm.controller;
import com.htttdn.crm.entity.*; import com.htttdn.crm.repository.SurveyRepository; import com.htttdn.crm.dto.admin.AdminDtos.*; import jakarta.transaction.Transactional; import jakarta.validation.Valid; import org.springframework.data.domain.Page; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/admin/surveys") public class AdminSurveyController extends AdminPageSupport { private final SurveyRepository surveys; public AdminSurveyController(SurveyRepository surveys){this.surveys=surveys;}
 @GetMapping public Page<Survey> list(@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return status==null?surveys.findAll(page(page,size)):surveys.findByStatus(status,page(page,size));}
 @PostMapping @Transactional public Survey create(@Valid @RequestBody SurveyRequest r){Survey survey=new Survey();survey.setTitle(r.title());survey.setDescription(r.description());survey.setStartsAt(r.startsAt());survey.setEndsAt(r.endsAt());for(int i=0;i<r.questions().size();i++){QuestionRequest q=r.questions().get(i);SurveyQuestion question=new SurveyQuestion();question.setSurvey(survey);question.setText(q.text());question.setType(q.type());question.setDisplayOrder(i);question.setOptionsJson(q.optionsJson());survey.getQuestions().add(question);}return surveys.save(survey);}
 @PatchMapping("/{id}/publish") public Survey publish(@PathVariable Long id,@RequestParam(defaultValue="true")boolean value){Survey survey=surveys.findById(id).orElseThrow();survey.setStatus(value?"PUBLISHED":"DRAFT");return surveys.save(survey);}
 @DeleteMapping("/{id}") public void delete(@PathVariable Long id){if(!surveys.existsById(id))throw new NoSuchElementException("Survey not found");surveys.deleteById(id);} }
